"import https from 'https';

async function fetchUrl(url: string): Promise<string> {
  return new Promise((resolve, reject) => {
    https.get(url, { headers: { 'User-Agent': 'Mozilla/5.0' } }, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => resolve(data));
    }).on('error', reject);
  });
}

async function testFeeds() {
  console.log("Testing market price feeds...");

  // 1. CoinGecko for Crypto & USDTRY reference
  try {
    const cg = await fetchUrl('https://api.coingecko.com/api/v3/simple/price?ids=bitcoin,ethereum,tether&vs_currencies=try,usd');
    console.log("CoinGecko:", cg);
  } catch (e) {
    console.log("CoinGecko error:", e);
  }

  // 2. Yahoo Finance for BIST (e.g. THYAO.IS)
  try {
    const yf = await fetchUrl('https://query1.finance.yahoo.com/v8/finance/chart/THYAO.IS?interval=1d&range=1d');
    const parsed = JSON.parse(yf);
    const meta = parsed.chart?.result?.[0]?.meta;
    console.log("Yahoo Finance THYAO.IS regularMarketPrice:", meta?.regularMarketPrice, meta?.currency);
  } catch (e) {
    console.log("Yahoo Finance error:", e);
  }

  // 3. TCMB today.xml for FX
  try {
    const tcmb = await fetchUrl('https://www.tcmb.gov.tr/kurlar/today.xml');
    console.log("TCMB fetched length:", tcmb.length, "contains USD:", tcmb.includes('USD'));
  } catch (e) {
    console.log("TCMB error:", e);
  }
}

testFeeds();
"

"import https from 'https';

async function fetchUrl(url: string): Promise<string> {
