      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => resolve(data));
    }).on('error', reject);
  });
}

async function testGold() {
  try {
    const yfGold = await fetchUrl('https://query1.finance.yahoo.com/v8/finance/chart/GC=F?interval=1d&range=1d');
    const parsedGold = JSON.parse(yfGold);
    const goldOz = parsedGold.chart?.result?.[0]?.meta?.regularMarketPrice;

    const yfUsd = await fetchUrl('https://query1.finance.yahoo.com/v8/finance/chart/USDTRY=X?interval=1d&range=1d');
    const parsedUsd = JSON.parse(yfUsd);
    const usdTry = parsedUsd.chart?.result?.[0]?.meta?.regularMarketPrice;

    console.log(`Ons Altın (USD): $${goldOz}, USD/TRY: ₺${usdTry}`);
    const gramAltinTry = (goldOz / 31.1034768) * usdTry;
    const ceyrekAltinTry = gramAltinTry * 1.635;
    console.log(`Hesaplanan Gram Altın (TRY): ₺${gramAltinTry.toFixed(2)}`);
    console.log(`Hesaplanan Çeyrek Altın (TRY): ₺${ceyrekAltinTry.toFixed(2)}`);
  } catch (e) {
    console.log("Gold error:", e);
  }

  // Also test BIST symbol search
  try {
    const searchRes = await fetchUrl('https://query1.finance.yahoo.com/v1/finance/search?q=thy&quotesCount=3');
    const quotes = JSON.parse(searchRes).quotes;
    console.log("BIST Search result for 'thy':", quotes?.map((q: any) => ({ symbol: q.symbol, shortname: q.shortname })));
  } catch (e) {
    console.log("Search error:", e);
  }
}

testGold();
