  let sum = 0
  for (const t of installmentTxs) {
    const m = t.recurrence.match(/(\d+)\/(\d+)/)
    if (m) {
      const current = parseInt(m[1], 10)
      const total = parseInt(m[2], 10)
      const remaining = Math.max(0, total - current)
      console.log(`- [${t.date}] ${t.merchant} | Açıklama: ${t.description} | Recurrence: ${t.recurrence} | Tutar: ${t.amount} TL | Kalan Ay: ${remaining}`)
      if (remaining > 0) {
        sum += Number(t.amount)
      }
    }
  }
  console.log('Total Active Installments Sum:', sum)

  const { data: subs } = await supabase.from('subscriptions').select('*')
  console.log('\nSubscriptions count:', subs?.length)
  if (subs) {
    for (const s of subs) {
      console.log(`- ${s.name} | ${s.amount} TL | Durum: ${s.status} | Karar: ${s.decision}`)
    }
  }
}

main()
