"const supabaseUrl = 'https://kvyslscyepxvkrcgsvvz.supabase.co'
const supabaseServiceKey = 'sb_secret_vPvXHuM3z_PHFOTDPz_RxA_75tKKrUE'

async function query() {
  const res = await fetch(`${supabaseUrl}/rest/v1/transactions?select=*&order=date.desc`, {
    headers: {
      'apikey': supabaseServiceKey,
      'Authorization': `Bearer ${supabaseServiceKey}`
    }
  })
  const txs = await res.json()

  // Group by user_id
  const byUser = {}
  for (const t of txs) {
    if (!byUser[t.user_id]) byUser[t.user_id] = []
    byUser[t.user_id].push(t)
  }

  for (const [userId, userTxs] of Object.entries(byUser)) {
    console.log(`\n================ User: ${userId} (Total Txs: ${userTxs.length}) ================`)

    // Exactly what page.tsx does:
    const activeInstallments = userTxs
      .filter((t) => t.recurrence && /Taksit\s*\(\d+\/\d+\)/i.test(t.recurrence))
      .map((t) => {
        const m = t.recurrence.match(/(\d+)\/(\d+)/)
        if (!m) return null
        const current = parseInt(m[1], 10)
        const total = parseInt(m[2], 10)
        const remaining = Math.max(0, total - current)
        return remaining > 0 ? { t, current, total, remaining, amountPerMonth: t.amount } : null
      })
      .filter(Boolean)

    let sum = 0
    console.log('Aktif Devam Eden Taksitler:')
    for (const item of activeInstallments) {
      console.log(`  - [${item.t.date}] ${item.t.merchant} | "${item.t.description}" | Recurrence: ${item.t.recurrence} | Tutar: ${item.amountPerMonth} TL (Kalan: ${item.remaining} ay)`)
      sum += Number(item.amountPerMonth || 0)
    }
    console.log(`>>> Bu Kullanıcının Devam Eden Taksit Toplamı: ${sum.toFixed(2)} TL`)
  }
}

query().catch(console.error)
"

